          variant="ghost"
          size="sm"
          icon={<Pencil className="size-4" />}
        >
          Edit Comment
        </Button>
      }
      title="Edit Comment"
      submitButton={
        <Button
          isLoading={updateCommentMutation.isPending}
          form="edit-comment"
          type="submit"
          size="sm"
          disabled={updateCommentMutation.isPending}
        >
          Submit
        </Button>
      }
    >
      <Form
        id="edit-comment"
        onSubmit={(values) => {
          updateCommentMutation.mutate({
            commentId: id,
            data: values,
          });
        }}
        schema={updateCommentInputSchema}
        options={{
          defaultValues: {
            body: currentBody,
          },
        }}
      >
        {({ register, formState }) => (
          <Textarea
            label="Body"
            error={formState.errors['body']}
            registration={register('body')}
          />
        )}
      </Form>
    </FormDrawer>
  );
};

