import { ArchiveX } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { MDPreview } from '@/components/ui/md-preview';
import { Spinner } from '@/components/ui/spinner';
import { useUser } from '@/lib/auth';
import { POLICIES, Authorization } from '@/lib/authorization';
import { User } from '@/types/api';
import { formatDate } from '@/utils/format';

import { useInfiniteComments } from '../api/get-comments';

import { DeleteComment } from './delete-comment';
import { EditComment } from './edit-comment';

type CommentsListProps = {
  discussionId: string;
};

export const CommentsList = ({ discussionId }: CommentsListProps) => {
  const user = useUser();
  const commentsQuery = useInfiniteComments({ discussionId });

  if (commentsQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const comments = commentsQuery.data?.pages.flatMap((page) => page.data);

  if (!comments?.length)
    return (
      <div
        role="list"
        aria-label="comments"
        className="flex h-40 flex-col items-center justify-center bg-white text-gray-500"
      >
        <ArchiveX className="size-10" />
        <h4>No Comments Found</h4>
      </div>
    );

  return (
    <>
      <ul aria-label="comments" className="flex flex-col space-y-3">
        {comments.map((comment, index) => (
          <li
            aria-label={`comment-${comment.body}-${index}`}
            key={comment.id || index}
            className="w-full bg-white p-4 shadow-sm"
          >
            <div className="flex justify-between">
              <div>
                <span className="text-xs font-semibold">
                  {formatDate(comment.createdAt)}
                </span>
                {comment.author && (
                  <span className="text-xs font-bold">
                    {' '}
                    by {comment.author.firstName} {comment.author.lastName}
                  </span>
                )}
              </div>
              <Authorization
                policyCheck={POLICIES['comment:delete'](
                  user.data as User,
                  comment,
                )}
              >
                <div className="flex space-x-2">
                  <EditComment
                    id={comment.id}
                    discussionId={discussionId}
                    currentBody={comment.body}
                  />
                  <DeleteComment
                    discussionId={discussionId}
                    id={comment.id}
                  />
                </div>
              </Authorization>
            </div>

            <MDPreview value={comment.body} />
          </li>
        ))}
      </ul>
      {commentsQuery.hasNextPage && (
        <div className="flex items-center justify-center py-4">
          <Button onClick={() => commentsQuery.fetchNextPage()}>
            {commentsQuery.isFetchingNextPage ? (
              <Spinner />
            ) : (
              'Load More Comments'
            )}
          </Button>
        </div>
      )}
    </>
  );
};

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';
import { Comment } from '@/types/api';

import { getInfiniteCommentsQueryOptions } from './get-comments';

export const updateCommentInputSchema = z.object({
  body: z.string().min(1, 'Required'),
});

export type UpdateCommentInput = z.infer<typeof updateCommentInputSchema>;

export const updateComment = ({
  commentId,
  data,
}: {
  commentId: string;
  data: UpdateCommentInput;
}): Promise<Comment> => {
  return api.patch(`/comments/${commentId}`, data);
};

type UseUpdateCommentOptions = {
  discussionId: string;
  mutationConfig?: MutationConfig<typeof updateComment>;
};

export const useUpdateComment = ({
  mutationConfig,
  discussionId,
}: UseUpdateCommentOptions) => {
  const queryClient = useQueryClient();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      queryClient.invalidateQueries({
        queryKey: getInfiniteCommentsQueryOptions(discussionId).queryKey,
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateComment,
  });
};

import { Pencil } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { FormDrawer, Form, Textarea } from '@/components/ui/form';
import { useNotifications } from '@/components/ui/notifications';

import {
  useUpdateComment,
  updateCommentInputSchema,
} from '../api/update-comment';

type EditCommentProps = {
  id: string;
  discussionId: string;
  currentBody: string;
};

export const EditComment = ({ id, discussionId, currentBody }: EditCommentProps) => {
  const { addNotification } = useNotifications();
  const updateCommentMutation = useUpdateComment({
    discussionId,
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'Comment Updated',
        });
      },
    },
  });

  return (
    <FormDrawer
      isDone={updateCommentMutation.isSuccess}
      triggerButton={
        <Button
          variant="ghost"
          size="sm"
          icon={<Pencil className="size-4" />}
        >
          Edit Comment
        </Button>
      }
      title="Edit Comment"
      submitButton={
        <Button
          isLoading={updateCommentMutation.isPending}
          form="edit-comment"
          type="submit"
          size="sm"
          disabled={updateCommentMutation.isPending}
        >
          Submit
        </Button>
      }
    >
      <Form
        id="edit-comment"
        onSubmit={(values) => {
          updateCommentMutation.mutate({
            commentId: id,
            data: values,
          });
        }}
        schema={updateCommentInputSchema}
        options={{
          defaultValues: {
            body: currentBody,
          },
        }}
      >
        {({ register, formState }) => (
          <Textarea
            label="Body"
            error={formState.errors['body']}
            registration={register('body')}
          />
        )}
      </Form>
    </FormDrawer>
  );
};
